    10	/**
    11	 * Run `fn` inside a transaction. Rolls back on throw.
    12	 */
    13	export async function withTransaction<T>(fn: (client: PoolClient) => Promise<T>): Promise<T> {
    14	  const client = await pool.connect();
    15	  try {
    16	    await client.query("BEGIN");
    17	    const result = await fn(client);
    18	    await client.query("COMMIT");
    19	    return result;
    20	  } catch (err) {
    21	    await client.query("ROLLBACK");
    22	    throw err;
    23	  } finally {
    24	    client.release();
    25	  }
    26	}
